{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        { "speaker": "partner", "text": "Would you like to dance?" },
        { "speaker": "you", "text": "I'd love to." },
        { "speaker": "you", "text": "I'm taking a break right now.", "or": true },
        { "speaker": "partner", "text": "No worries at all." },
        { "speaker": "partner", "text": "Maybe next song.", "or": true }
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        { "speaker": "you", "text": "You're a great dancer." },
        { "speaker": "partner", "text": "Thank you so much." },
        { "speaker": "you", "text": "Where did you learn to move like that?" },
        { "speaker": "partner", "text": "I take classes downtown." },
        { "speaker": "partner", "text": "I just practice a lot.", "or": true }
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        { "speaker": "you", "text": "Do you come here often?" },
        { "speaker": "partner", "text": "Every weekend." },
        { "speaker": "partner", "text": "This is my first time here.", "or": true },
        { "speaker": "you", "text": "The live band tonight is amazing." },
        { "speaker": "partner", "text": "They always play great music." }
      ]
    }
  ]
}
